def transform(grid):
    h, w = len(grid), len(grid[0])

    # The colored motif is the least frequent nonzero color.
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    motif_color = min(counts, key=counts.get)

    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == motif_color]
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    shape = [(r - min_r, c - min_c) for r, c in cells]
    shape_h = max(r for r, c in shape) + 1
    shape_w = max(c for r, c in shape) + 1

    out = [row[:] for row in grid]
    for top in range(h - shape_h + 1):
        for left in range(w - shape_w + 1):
            if all(grid[top + r][left + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[top + r][left + c] = motif_color

    return out
